output-exprs.el:
catalogos_out:if(
  and(
    a!isNotNullOrEmpty(pv!catalogos_out),
    a!isNotNullOrEmpty(pv!catalogos_out.siefores),
    lenght(pv!catalogos_out.siefores) > 0
  ),
  catalogos_out: {
    codigo: pv!catalogos_out.codRet,
    descripcion: "Consulta Exitosa"
  },
  {
    codigo: pv!catalogos_out.codRet,
    descripcion: pv!catalogos_out.descRet
  }
)

